#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> values{7, 2, 5};
    std::sort(values.begin(), values.end());
    const bool found = std::binary_search(values.begin(), values.end(), 5);
    std::cout << values.front() << ", found=" << std::boolalpha << found << '\n';
}
